-- --------------------------------------------------------
-- Structure for table `pelaku_usaha`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `pelaku_usaha`;
CREATE TABLE `pelaku_usaha` (
  `id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nib` VARCHAR(255) NULL,
  `nik` VARCHAR(255) NULL,
  `skala_usaha` VARCHAR(255) NULL,
  `jenis_perusahaan` VARCHAR(255) NULL,
  `nama_perusahaan` VARCHAR(255) NULL,
  `nama_proyek` VARCHAR(255) NULL,
  `nama_pemilik` VARCHAR(255) NULL,
  `alamat_usaha` LONGTEXT NULL,
  `kecamatan` VARCHAR(255) NULL,
  `kbli` VARCHAR(255) NULL,
  `uraian_kbli` LONGTEXT NULL,
  `tingkat_risiko` VARCHAR(255) NULL,
  `investasi` VARCHAR(255) NULL,
  `tenaga_kerja` INT(11) NULL DEFAULT '0',
  `no_telp` VARCHAR(255) NULL,
  `email` VARCHAR(255) NULL,
  `tgl_terbit` VARCHAR(255) NULL,
  `nama_usaha` VARCHAR(255) NULL,
  `pemilik` VARCHAR(255) NULL,
  `alamat` VARCHAR(255) NULL,
  `kelurahan` VARCHAR(255) NULL,
  `latitude` VARCHAR(255) NULL,
  `longitude` VARCHAR(255) NULL,
  `kategori` VARCHAR(255) NULL,
  `created_at` TIMESTAMP NULL DEFAULT NULL,
  `updated_at` TIMESTAMP NULL DEFAULT NULL,
  `status` VARCHAR(255) NULL,
  `sertifikat_halal` VARCHAR(255) NULL,
  `bpom` VARCHAR(255) NULL,
  `cppob` VARCHAR(255) NULL,
  `sni` VARCHAR(255) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

