-- --------------------------------------------------------
-- Structure for table `peta_sebaran`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `peta_sebaran`;
CREATE TABLE `peta_sebaran` (
  `id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nama_usaha` VARCHAR(255) NULL,
  `pemilik` VARCHAR(255) NULL,
  `nib` VARCHAR(255) NULL,
  `link_gdrive_nib` VARCHAR(255) NULL,
