-- --------------------------------------------------------
-- Structure for table `list_kegiatan`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `list_kegiatan`;
CREATE TABLE `list_kegiatan` (
  `id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nama_kegiatan` VARCHAR(255) NULL,
  `sub_pelaksana` VARCHAR(255) NULL,
  `tgl_mulai` TIMESTAMP NULL DEFAULT NULL,
  `tgl_selesai` TIMESTAMP NULL DEFAULT NULL,
  `tempat_kegiatan` VARCHAR(255) NULL,
  `kuota_peserta` INT(11) NULL DEFAULT '0',
  `deskripsi_kegiatan` LONGTEXT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT '0',
  `status` VARCHAR(255) NULL,
  `created_at` TIMESTAMP NULL DEFAULT NULL,
  `updated_at` TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

