-- --------------------------------------------------------
-- Structure for table `registrasi_pelatihan`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `registrasi_pelatihan`;
CREATE TABLE `registrasi_pelatihan` (
  `id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nama_kegiatan` VARCHAR(255) NULL,
  `nama_lengkap` VARCHAR(255) NULL,
  `nik` VARCHAR(255) NULL,
  `nib` VARCHAR(255) NULL,
  `email` VARCHAR(255) NULL,
  `whatsapp` VARCHAR(255) NULL,
  `jenis_kelamin` VARCHAR(255) NULL,
  `tanggal_lahir` TIMESTAMP NULL DEFAULT NULL,
  `foto_ktp` VARCHAR(255) NULL,
  `foto_produk` LONGTEXT NULL,
  `nama_usaha` VARCHAR(255) NULL,
  `produk_diproduksi` VARCHAR(255) NULL,
  `alamat_usaha` LONGTEXT NULL,
  `kelurahan` VARCHAR(255) NULL,
  `kecamatan` VARCHAR(255) NULL,
  `kota` VARCHAR(255) NULL,
  `jenis_usaha` VARCHAR(255) NULL,
  `tahun_mulai` VARCHAR(255) NULL,
  `skala_usaha` VARCHAR(255) NULL,
  `omzet_bulanan` VARCHAR(255) NULL,
  `stabilitas_omzet` VARCHAR(255) NULL,
  `tantangan_usaha` LONGTEXT NULL,
  `media_penjualan` LONGTEXT NULL,
  `cakupan_pemasaran` LONGTEXT NULL,
  `karyawan_tetap` INT(11) NULL DEFAULT '0',
  `karyawan_tidak_tetap` INT(11) NULL DEFAULT '0',
  `sistem_usaha` VARCHAR(255) NULL,
  `level_digital` VARCHAR(255) NULL,
  `pernah_pelatihan` VARCHAR(255) NULL,
  `harapan_pelatihan` VARCHAR(255) NULL,
  `target_6_bulan` VARCHAR(255) NULL,
  `is_lolos` TINYINT(1) NOT NULL DEFAULT '0',
  `created_at` TIMESTAMP NULL DEFAULT NULL,
  `updated_at` TIMESTAMP NULL DEFAULT NULL,
  `deleted_at` TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

