INSERT INTO `publikasi` (`id`, `judul`, `gambar`, `tanggal`, `waktu`, `deskripsi`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('4', 'Pelatihan Pengrajin Tahu', '/uploads/publikasi/tahu_training.png', '2026-06-17', '08.00 Selesai', 'Pelatihan pengrajin tahu bertujuan meningkatkan kualitas produksi, higienitas, inovasi rasa, pengemasan, manajemen usaha, serta pemasaran digital agar produk tahu lebih bernilai, berdaya saing, dan mampu meningkatkan pendapatan pelaku usaha lokal.', 'Belum Dimulai', '1', '2026-03-26 19:02:55', '2026-07-30 21:53:50');
INSERT INTO `publikasi` (`id`, `judul`, `gambar`, `tanggal`, `waktu`, `deskripsi`, `status`, `is_active`, `created_at`, `updated_at`) VALUES ('5', 'Pelatihan Pengrajin tempe', '/uploads/publikasi/tempe_training.png', '2026-03-24', '08.00 Selesai', 'Pelatihan pengrajin tempe bertujuan meningkatkan keterampilan produksi yang higienis dan konsisten, pemilihan bahan baku berkualitas, inovasi varian produk, teknik pengemasan modern, serta strategi pemasaran digital. Selain itu, peserta dibekali manajemen usaha sederhana agar mampu meningkatkan daya saing, memperluas pasar, dan menaikkan pendapatan secara berkelanjutan.', 'Selesai', '1', '2026-03-26 19:42:37', '2026-07-24 08:37:12');
