-- --------------------------------------------------------
-- Structure for table `statistik_kecamatan`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `statistik_kecamatan`;
CREATE TABLE `statistik_kecamatan` (
  `id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `kecamatan` VARCHAR(255) NULL,
  `jumlah_ikm` INT(11) NULL DEFAULT '0',
  `updated_at` TIMESTAMP NULL DEFAULT NULL,
  `jumlah` VARCHAR(255) NULL,
  `total_kunjungan` VARCHAR(255) NULL,
  `pengunjung_aktif` VARCHAR(255) NULL,
  `ikm_terdaftar` VARCHAR(255) NULL,
  `kunjungan_hari_ini` VARCHAR(255) NULL,
  `kunjungan_bulan_ini` VARCHAR(255) NULL,
  `kunjungan_tahun_ini` VARCHAR(255) NULL,
  `kunjungan_total` VARCHAR(255) NULL,
  `sosial_media` LONGTEXT NULL,
  `telp_dinas` VARCHAR(255) NULL,
  `email_dinas` VARCHAR(255) NULL,
  `fonnte_token` VARCHAR(255) NULL,
  `admin_wa_number` VARCHAR(255) NULL,
  `wa_notif_active` TINYINT(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

